{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "De fire punkter er i store træk i overensstemmelse med kilden. Svaret gengiver dog ikke, at tidligere arbejde især er relevant, når ophøret skyldtes andre forhold end funktionsnedsættelsen, og at der ikke er sket forværring. Det angiver heller ikke, at oplysningerne indgår i en samlet vurdering. Afslutningen siger, at oplysningerne bruges til at vurdere, om ansøgeren har ret til tillægget. Det er upræcist og kan læses, som om oplysningerne alene afgør retten."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Tre af de fire kritiske elementer er med: Skattestyrelsens oplysninger, ansøgerens egne oplysninger og arbejde under studiet. Det tredje mangler: arbejde før ansøgningen kan indgå, navnlig når ophøret skyldtes andre forhold end funktionsnedsættelsen, og denne ikke er forværret efter ophøret. Svaret nævner kun, at oplysninger om tidligere erhvervsarbejde bruges."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer spørgsmålet om, hvilke arbejds- og indkomstoplysninger Udbetaling Danmark bruger, og indeholder ikke irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledningsafsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det ikke kan vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Punkterne 1-4 har dækning i vejledningens afsnit 3.4.1.3. Afslutningen med 'varig fysisk eller psykisk funktionsnedsættelse ... meget betydelige begrænsninger' svarer til SU-lovens § 7, stk. 3. Svaret tilføjer ikke nogen regel, betingelse eller myndighed uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Den krævede kvalifikation mangler. Det fremgår ikke, at forholdene ved tidligere arbejde er særligt relevante situationer og ikke udtømmende betingelser, eller at oplysningerne ikke alene afgør retten. Forbeholdet 'kan indgå' er også udeladt, så tidligere arbejde fremstår som en fast del af vurderingen."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en kort opremsning efterfulgt af en generel afslutning, og de to dele er ikke i indbyrdes modstrid."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Kilden siger, at oplysninger om tidligere erhvervsarbejde 'kan indgå'. Svaret skriver, at Udbetaling Danmark 'bruger' dem, og gør dermed en mulighed til fast praksis. Det siger også, at oplysningerne bruges til at vurdere, om ansøgeren 'har ret' til tillægget, uden at angive, at de indgår i en samlet vurdering."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "yes",
      "reason": "Svaret nævner, at oplysninger om arbejdstimer og indkomst kommer fra Skattestyrelsen."
    },
    "A19": {
      "label": "yes",
      "reason": "Svaret nævner ansøgerens egne oplysninger om tidligere arbejdsforhold, som skal angives i ansøgningen."
    },
    "A20": {
      "label": "partial",
      "reason": "Svaret nævner erhvervsarbejde før ansøgningen og under studiet. Det udelader dog 'kan indgå', 'navnlig'-situationen om arbejdsophør af andre grunde og manglende forværring."
    }
  },
  "overall_notes": "Svaret gengiver de grundlæggende oplysningskilder korrekt, men udelader den centrale nuance om tidligere arbejde og de relevante forbehold. Det angiver ingen kilder."
}

